import re

result = []

# 删除以下类型内容：
# !image-xxx.png!
# !screenshot-xxx.png!
# !screenshot-xxx.png|thumbnail!
# [~username]  (username 任意)
pattern = re.compile(
    r'!(?:image|screenshot)-[\w\-]+\.png(?:\|thumbnail)?!|\[~[^\]]+\]'
)

exclude_keywords = ["详细信息请参见链接"]

for item in items:
    comments = item.get("json", {}).get("comments", [])

    for comment in comments:
        # 跳过包含排除关键词的评论
        if any(keyword in comment for keyword in exclude_keywords):
            continue

        # 删除匹配内容，并合并多余空格
        cleaned = re.sub(pattern, '', comment)
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()

        if cleaned:
            result.append(cleaned)

return [{
    "json": {
        "comments": result
    }
}]

import re

output_items = []

# 清理 <think> ... </think> 内容
think_pattern = re.compile(r"<think>.*?</think>", re.DOTALL | re.IGNORECASE)

# QA 匹配正则：question/indexes/answer 可出现也可缺失，顺序不固定，但按 question 首先匹配
field_pattern = re.compile(
    r'(问题总结|问题现象|具体复现步骤)\s*:\s*["\']?(.*?)["\']?(?=\s*(问题总结|问题现象|具体复现步骤)\s*:|\Z)',
    re.IGNORECASE | re.DOTALL
)

def safe_str(val):
    if val is None:
        return ""
    try:
        return str(val)
    except Exception:
        return ""

for item in _input.all():
    raw_text = safe_str(item.json.get("output", ""))
    path = safe_str(item.json.get("path", ""))

    q_val, a_val, idx_val = "", "", ""

    if raw_text.strip():
        # ① 清理 <think>
        cleaned_text = think_pattern.sub("", raw_text).strip()

        # ② 匹配所有字段
        matches = field_pattern.findall(cleaned_text)

        # ③ 提取各字段
        for field, value, _ in matches:
            field_lower = field.lower().strip()
            val = safe_str(value).strip()
            if field_lower == "问题总结":
                q_val = val
            elif field_lower == "问题现象":
                a_val = val
            elif field_lower == "具体复现步骤":
                idx_val = val

    # 输出
    output_items.append({
        "json": {
            "output": cleaned_text,

        }
    })

return output_items

